STATUS = '#!/usr/bin/env python3\n"""Penulis /marimo/llm/status.json — dipakai dashboard marimo untuk progress realtime."""\nfrom __future__ import annotations\n\nimport json\nimport os\nimport shutil\nimport subprocess\nimport time\n\nMODEL_DIR = "/home/marimo/models/sc117/IQ3_S"\nTOTAL_BYTES = 83_863_586_496          # shard1 + shard2\nPHASE_FILE = "/marimo/llm/phase"\nOUT = "/marimo/llm/status.json"\nKEY = open("/marimo/llm/api_key.txt").read().strip() if os.path.exists("/marimo/llm/api_key.txt") else ""\n\nLABEL = {\n    "start": "menyiapkan",\n    "strata": "memasang Strata",\n    "download": "mengunduh model",\n    "aux": "mengunduh runtime",\n    "prep": "menyiapkan berkas",\n    "launch": "memuat model ke GPU",\n    "relay": "menyambung ke Cloudflare",\n    "done": "selesai",\n}\n\n\ndef du(path: str) -> int:\n    total = 0\n    for root, _dirs, files in os.walk(path):\n        for f in files:\n            try:\n                total += os.path.getsize(os.path.join(root, f))\n            except OSError:\n                pass\n    return total\n\n\ndef ram_gb() -> float:\n    try:\n        with open("/proc/meminfo") as fh:\n            info = {line.split(":")[0]: int(line.split()[1]) for line in fh if ":" in line}\n        return round((info["MemTotal"] - info["MemAvailable"]) / 1024 / 1024, 1)\n    except Exception:  # noqa: BLE001\n        return 0.0\n\n\ndef vram_gb() -> float:\n    try:\n        out = subprocess.run(\n            ["nvidia-smi", "--query-gpu=memory.used", "--format=csv,noheader,nounits"],\n            capture_output=True, text=True, timeout=3).stdout.strip().splitlines()\n        return round(int(out[0]) / 1024, 1) if out else 0.0\n    except Exception:  # noqa: BLE001\n        return 0.0\n\n\ndef http_code(url: str, timeout: int = 3) -> int:\n    try:\n        out = subprocess.run(\n            ["curl", "-s", "-m", str(timeout), "-o", "/dev/null", "-w", "%{http_code}",\n             url, "-H", f"Authorization: Bearer {KEY}"],\n            capture_output=True, text=True, timeout=timeout + 3).stdout.strip()\n        return int(out or 0)\n    except Exception:  # noqa: BLE001\n        return 0\n\n\ndef main() -> None:\n    t0 = time.time()\n    last_bytes, last_t = 0, t0\n    speed = 0.0\n    while True:\n        try:\n            phase = open(PHASE_FILE).read().strip() or "start"\n        except OSError:\n            phase = "start"\n\n        downloading = phase in ("download", "aux")\n        size = du(MODEL_DIR) if phase in ("download", "aux", "prep", "launch") else TOTAL_BYTES\n        now = time.time()\n        if not downloading:\n            speed = 0.0\n            last_bytes, last_t = size, now\n        elif now - last_t >= 2:\n            inst = (size - last_bytes) / (now - last_t) / 1e6\n            speed = inst if inst >= 0 else speed\n            last_bytes, last_t = size, now\n\n        pct = 100.0 if phase in ("done",) else min(99.9, size / TOTAL_BYTES * 100)\n        eta = int((TOTAL_BYTES - size) / (speed * 1e6)) if speed > 1 and size < TOTAL_BYTES else 0\n\n        server = public = 0\n        if phase in ("launch", "relay", "done"):\n            server = http_code("http://127.0.0.1:8081/v1/models")\n        if phase in ("relay", "done"):\n            public = http_code("https://ai.wanz4bigel.dpdns.org/v1/models", 5)\n\n        state = {\n            "t": time.strftime("%H:%M:%S"),\n            "elapsed_s": int(now - t0),\n            "phase": phase,\n            "phase_label": LABEL.get(phase, phase),\n            "model_gb": round(size / 1e9, 1),\n            "total_gb": round(TOTAL_BYTES / 1e9, 1),\n            "pct": round(pct, 1),\n            "speed_mbps": round(speed, 0),\n            "eta_s": eta,\n            "ram_gb": ram_gb(),\n            "vram_gb": vram_gb(),\n            "server": server,\n            "public": public,\n        }\n        tmp = OUT + ".tmp"\n        with open(tmp, "w") as fh:\n            json.dump(state, fh)\n        os.replace(tmp, OUT)\n        time.sleep(2)\n\n\nif __name__ == "__main__":\n    main()\n'
CELL = 'import json\nimport pathlib\n\nimport marimo as mo\n\nrefresh = mo.ui.refresh(default_interval="2s")\n\ntry:\n    s = json.loads(pathlib.Path("/marimo/llm/status.json").read_text())\nexcept Exception:\n    s = {}\n\npct = float(s.get("pct") or 0)\nfilled = int(round(pct / 100 * 30))\nbar = "█" * filled + "░" * (30 - filled)\neta = int(s.get("eta_s") or 0)\neta_txt = f"{eta // 60}m{eta % 60:02d}s" if eta else "—"\nlive = s.get("public") == 200\nkey = pathlib.Path("/marimo/llm/api_key.txt").read_text().strip() if pathlib.Path("/marimo/llm/api_key.txt").exists() else ""\n\nmo.vstack([\n    mo.md(f"""\n# IQ3_S (SC117 abliterated) — {\'LIVE\' if live else \'sedang dibangun\'}\n\n| | |\n|---|---|\n| **Base URL** | `https://ai.wanz4bigel.dpdns.org/v1` |\n| **API key** | `{key}` |\n| **Model** | `swift-1.5-iq3_s` · 262.144 konteks · KV int8 |\n| **Fase** | **{s.get(\'phase_label\', \'—\')}** · {s.get(\'elapsed_s\', 0)} detik |\n| **Unduhan** | `{bar}` {pct:.1f}% · {s.get(\'model_gb\', 0)} / {s.get(\'total_gb\', 0)} GB · {int(s.get(\'speed_mbps\') or 0)} MB/s · ETA {eta_txt} |\n| **RAM / VRAM** | {s.get(\'ram_gb\', 0)} GB / {s.get(\'vram_gb\', 0)} GB |\n| **Server lokal / publik** | {s.get(\'server\', 0)} / {s.get(\'public\', 0)} |\n| **Diperbarui** | {s.get(\'t\', \'—\')} |\n\nModel ada di `/home/marimo/models/sc117` (disk, bukan `/dev/shm`), jadi RAM lega.\n\nKalau sandbox mati: **Relaunch** di molab → `bash /marimo/llm/pipeline.sh`.\nDashboard ini akan menampilkan progres unduhan secara langsung.\n"""),\n    refresh,\n])\n'

